using CommonObjects;
using CommonObjects.Constants;
using Tekla.Structures.Ui.WpfKit.Commands;
using System.ComponentModel;
using TSG = Tekla.Structures.Geometry3d;
using Tekla.Structures.Model;
using TSM = Tekla.Structures.Model;
using Tekla.Structures.Model.UI;
using System.Collections.Generic;
using System.Threading;
using Tekla.Structures.CustomObjectType;

namespace ExampleBeamFeature
{
    // delegates
    private delegate void CommandRepository_CommandExecuting(string commandId);
    private delegate void PropertyPane_InitializeForCustomObjectTypeCreation(string customObjectType);

    // privates
    private TsCommand exampleBeamCommand;
    private TsCommand.CommandContext exampleBeamCommandMutator;
    private const string CustomBeam = "CustomBeam";

    public class ExampleCustomBeamFeature : CustomObjectTypeFeatureBase
    {
        public ExampleCustomBeamFeature()
        {
            this.exampleBeamCommand = TsCommand.Create(CustomBeam, CommandAvailabilities.Modeling,
                _ =>
                {
                    this.Host.Invoke((PropertyPane_InitializeForCustomObjectTypeCreation m) => m(CustomBeam));
                    this.Host.Invoke((CommandRepository_CommandExecuting m) => m(this.exampleBeamCommand.Id));
                    this.CreateCustomBeam();
                },
                out this.exampleBeamCommandMutator);
        }

        public override void Starting(CancelEventArgs starting)
        {
            this.exampleBeamCommand.ShortText = this.Host.UI.GetLocalizedText("albl_Custom_beam");
            this.exampleBeamCommand.FullText = this.Host.UI.GetLocalizedText("albl_Custom_beam");
            this.exampleBeamCommand.IconResourceKey = "Brush.CommandGallery.ConcretePolybeam_Active";
            this.exampleBeamCommand.ToolTip = "Create custom beam";
            this.InitializeFeature(CustomBeam, "Custom beam", "", new Beam(), this.exampleBeamCommand, this.exampleBeamCommandMutator, "");
        }

        public override void Running(string[] arguments)
        {
            this.UpdatePropertyTemplate();
        }

        internal void CreateCustomBeam()
        {
            var thread = new Thread(() =>
            {
                try
                {
                    var picker = new Picker();
                    var points = picker.PickPoints(Picker.PickPointEnum.PICK_TWO_POINTS, "Pick start and end point of the custom beam");
                    if (points!= null && points.Count == 2)
                    {
                        var beam = new Beam(points[0] as TSG.Point, points[1] as TSG.Point);

                        // Insert beam instance to database
                        beam = this.Insert(beam);

                        if (beam.Identifier.IsValid())
                        {
                            new Model().CommitChanges("Custom beam created");
                        }
                    }
                }
                catch { }
            });
            thread.Start();
        }

        private void UpdatePropertyTemplate()    
        {
            this.BuildPropertyTemplateFromBaseTemplate(Templates.Modeling.SteelBeam);
            this.AddPropertyGroupToPropertyPane("Prop", "Custom properties", this.GetProperties(), 1);
        }

        private List<PropertyBase> GetProperties()
        {
            var properties = new List<PropertyBase>(); 
            properties.Add(new MaterialProperty("CustomMat") { LayoutManipulatorType = typeof(MaterialLayoutManipulator), Label = "Custom material", Tooltip = "Custom material" };);
            return properties;
        }
    }
}
